//==========================================================================================
// Function to run the icon animation

void runIcon(Icon &icon, Adafruit_ST7789 &tft) {
  if (!icon.active) return;

  tft.drawRGBBitmap(icon.x, icon.y,
                    icon.frames[icon.currentFrame],
                    icon.width, icon.height);

  icon.currentFrame++;
  if (icon.currentFrame >= icon.frameCount) {
    icon.currentFrame = 0;
  }
}

